<template><div class="grid gap-2"><label v-for="option in options" :key="option.id" class="flex min-h-10 items-center gap-2 rounded-md border border-adm-line px-3 text-sm hover:bg-adm-surface-2"><input type="checkbox" :value="option.id" :checked="modelValue.includes(option.id)" @change="toggle(option.id,($event.target as HTMLInputElement).checked)"/><span>{{ option.name }}</span></label></div></template>
<script setup lang="ts">const props=defineProps<{modelValue:number[];options:{id:number;name:string}[]}>();const emit=defineEmits<{ 'update:modelValue':[value:number[]] }>();function toggle(id:number,checked:boolean){emit('update:modelValue',checked?[...props.modelValue,id]:props.modelValue.filter(item=>item!==id))}</script>
